package com.greenocean.backend;
import com.greenocean.backend.trust.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.common.exception.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import java.time.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.operations.enabled=true"})@ActiveProfiles("test")@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseQ3ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_q3_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired IncidentOperations operations;@Autowired TrustCoverage coverage;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 PhaseIFixtures.Actor a,b,c;
 @BeforeEach void setup(){PhaseIFixtures.region(db);a=operator();b=operator();c=operator();for(var worker:List.of(a,b,c)){var author=worker.equals(a)?b:a;UUID shift=coverage.schedule(author.id(),author.session(),"CLINIC",worker.id(),Instant.now().minusSeconds(10),Instant.now().plusSeconds(3600),1);coverage.acknowledge(worker.id(),worker.session(),shift);}db.execute("CREATE TABLE IF NOT EXISTS synthetic_admission_marker(id UUID PRIMARY KEY DEFAULT uuidv7(),admitted_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp())");}
 PhaseIFixtures.Actor operator(){var actor=PhaseIFixtures.member(db,users,tokens);for(String role:List.of("TRUST_PLATFORM","TRUST_CLINIC"))db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=?",actor.id(),role);db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",actor.session());return actor;}
 UUID incident(UUID key){return operations.detect(a.id(),a.session(),"CLINIC","SERVICE_FAILURE","SEV2",key,"SYNTHETIC:concurrent-operation");}
 Object acknowledge(PhaseIFixtures.Actor actor,UUID incident){operations.transition(actor.id(),actor.session(),incident,1,"ACKNOWLEDGED","SYNTHETIC:owner-acknowledgement");return "OWNED";}
 List<Object> race(Supplier<?> first,Supplier<?> second)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();try{return first.get();}catch(RuntimeException ex){return ex;}});var y=pool.submit(()->{start.await();try{return second.get();}catch(RuntimeException ex){return ex;}});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 @Test void duplicateDetectionAcrossConnectionsCreatesOneReferenceAndTimeline()throws Exception{UUID key=UUID.randomUUID();var results=race(()->incident(key),()->incident(key));assertThat(results.get(0)).isInstanceOf(UUID.class).isEqualTo(results.get(1));assertThat(db.queryForObject("SELECT count(*) FROM operation_incident_events WHERE incident_id=?",Integer.class,results.get(0))).isEqualTo(1);}
 @Test void conflictingOwnersCannotBothAcknowledgeTheSameRevision()throws Exception{UUID id=incident(UUID.randomUUID());var results=race(()->acknowledge(b,id),()->acknowledge(c,id));assertThat(results.stream().filter("OWNED"::equals).count()).isEqualTo(1);assertThat(results.stream().filter(ConflictException.class::isInstance).count()).isEqualTo(1);}
 @Test void oneStaffedCapacitySlotCannotOwnTwoConcurrentIncidents()throws Exception{UUID first=incident(UUID.randomUUID()),second=incident(UUID.randomUUID());var results=race(()->acknowledge(a,first),()->acknowledge(a,second));assertThat(results.stream().filter("OWNED"::equals).count()).isEqualTo(1);assertThat(results.stream().filter(ConflictException.class::isInstance).count()).isEqualTo(1);}
 @Test void admissionAndIndependentPauseSerializeWithNoPostPauseAdmission()throws Exception{UUID id=incident(UUID.randomUUID());acknowledge(a,id);UUID control=operations.propose(a.id(),a.session(),id,2,"CLINIC_BOOKING","PAUSE",null,"SYNTHETIC:race-containment");var tx=new TransactionTemplate(manager);UUID marker=UUID.randomUUID();var results=race(()->{operations.approve(b.id(),b.session(),id,control,2);return "PAUSED";},()->tx.execute(status->{AdmissionContainment.require(db,"CLINIC_BOOKING");db.update("INSERT INTO synthetic_admission_marker(id) VALUES(?)",marker);return "ADMITTED";}));assertThat(results).contains("PAUSED");for(Object result:results)assertThat(result instanceof String||result instanceof ForbiddenException).isTrue();assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isTrue();assertThatThrownBy(()->tx.execute(status->{AdmissionContainment.require(db,"CLINIC_BOOKING");return null;})).isInstanceOf(ForbiddenException.class);assertThat(db.queryForObject("SELECT count(*) FROM synthetic_admission_marker m JOIN operation_containment c ON c.id=? WHERE m.id=? AND m.admitted_at>c.approved_at",Integer.class,control,marker)).isZero();}
 @Test void roleRevocationAndShiftAcknowledgementDoNotDeadlockOrRestoreCoverage()throws Exception{var results=race(()->{UUID shift=db.queryForObject("SELECT id FROM trust_coverage WHERE operator_id=?",UUID.class,b.id());coverage.acknowledge(b.id(),b.session(),shift);return "ACKNOWLEDGED";},()->{db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='TRUST_CLINIC')",b.id());return "REVOKED";});assertThat(results).contains("REVOKED");for(Object result:results)assertThat(result instanceof String||result instanceof UnauthorizedException||result instanceof NotFoundException||result instanceof ForbiddenException).isTrue();assertThat(coverage.live("CLINIC",b.id())).isFalse();}
}
